WITH base AS (SELECT * FROM web_events WHERE event_type <> 'add_to_cart'), summary AS (SELECT DATE_TRUNC('MONTH', event_time) event_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) event_type_values, COUNT(DISTINCT duration_sec) unique_sessions FROM base GROUP BY DATE_TRUNC('MONTH', event_time)) SELECT * FROM summary WHERE unique_sessions > 9 ORDER BY event_type_values;
